from __future__ import annotations

"""Mobile V1 decision-detail App Ready hydration.

Decision intelligence is prefetched once per active App Ready generation. Detail
hydration resolves exact UPC + action before any family fallback, preventing a
related UPC in the same family from supplying the WHY evidence.
"""

_SCRIPT = r'''<script id="yipmanV1DecisionSnapshotScript">(()=>{'use strict';
const digits=v=>String(v??'').replace(/\D/g,'').replace(/^0+/,'');
let decisionPromise=null,decisionBuildId='';
const text=(root,sel)=>String(root?.querySelector(sel)?.textContent||'').trim();
const identity=(body,label)=>{for(const el of body.querySelectorAll('.v1-detail-id>div')){const k=text(el,'b').toUpperCase();if(k.includes(label))return text(el,'span')}return''};
const actionType=body=>String(body?.dataset?.actionType||identity(body,'ACTION')||text(body,'.v1-detail-action')||'').trim().toUpperCase().replace(/[\s-]+/g,'_');
const evidenceCell=(body,key,label,value)=>{if(value===null||value===undefined||value==='')return;let host=body.querySelector('.v1-detail-metrics');if(!host)return;let cell=[...host.querySelectorAll('[data-evidence-key]')].find(x=>x.dataset.evidenceKey===key);if(!cell){cell=document.createElement('div');cell.dataset.evidenceKey=key;cell.innerHTML='<b></b><span></span>';host.appendChild(cell)}cell.querySelector('b').textContent=label;cell.querySelector('span').textContent=String(value)};
function pick(obj,...keys){for(const k of keys){const v=obj?.[k];if(v!==null&&v!==undefined&&v!=='')return v}return null}
async function activeBuildId(){try{const r=await fetch('/api/yipman/app-ready/status',{cache:'no-store'});if(!r.ok)return'';const j=await r.json();return String(j?.active_build_id??j?.active?.build_id??j?.build_id??'')}catch{return''}}
async function preload(){const live=await activeBuildId();if(decisionPromise&&(!live||live===decisionBuildId))return decisionPromise;decisionBuildId=live;decisionPromise=fetch('/api/yipman/app-ready/decision_intelligence',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(env=>{const id=String(env?.build_id??env?.active_build_id??'');if(id)decisionBuildId=id;return env}).catch(()=>null);return decisionPromise}
function byKeyDecision(p,family,upc,action){const by=p?.by_key||p?.decisions;if(!by||typeof by!=='object')return null;const u=digits(upc),f=String(family||'').trim(),a=String(action||'').trim().toUpperCase();const keys=[];if(u&&a)keys.push(`UPC:${u}:${a}`);if(u)keys.push(`UPC:${u}`);if(f&&a)keys.push(`FAMILY:${f}:${a}`);if(f)keys.push(`FAMILY:${f}`);for(const k of keys){if(by[k])return by[k];if(by[k.toLowerCase()])return by[k.toLowerCase()]}return null}
function exactDecision(p,family,upc,action){const keyed=byKeyDecision(p,family,upc,action);if(keyed)return keyed;const u=digits(upc),f=String(family||'').trim(),a=String(action||'').trim().toUpperCase();const groups=[p?.pricing,p?.tpr_progress];for(const g of groups){const rows=Array.isArray(g)?g:Array.isArray(g?.rows)?g.rows:[];if(u){const exact=rows.find(r=>digits(r?.upc??r?.ean_upc??r?.ean)===u&&(!a||String(r?.recommendation_type??r?.suggestion_type??r?.price_type??'').toUpperCase().replace(/[\s-]+/g,'_')===a||a==='TPR_PROGRESS'));if(exact)return exact}}if(a==='ORDERING'||!a){for(const day of Object.values(p?.ordering?.deliveries||{})){const rows=Array.isArray(day)?day:Array.isArray(day?.rows)?day.rows:[];if(u){const exact=rows.find(r=>digits(r?.upc??r?.ean_upc??r?.ean)===u);if(exact)return exact}}}if(f){for(const g of groups){const rows=Array.isArray(g)?g:Array.isArray(g?.rows)?g.rows:[];const fam=rows.find(r=>String(r?.family??r?.family_article??r?.family_id??r?.main_article_number??'').trim()===f);if(fam)return fam}for(const day of Object.values(p?.ordering?.deliveries||{})){const rows=Array.isArray(day)?day:Array.isArray(day?.rows)?day.rows:[];const fam=rows.find(r=>String(r?.family??r?.family_article??r?.family_id??r?.main_article_number??'').trim()===f);if(fam)return fam}}return null}
async function hydrate(){const body=document.getElementById('v1DetailBody'),overlay=document.getElementById('v1DetailOverlay');if(!body||!overlay?.classList.contains('open'))return;const family=identity(body,'FAMILY'),upc=identity(body,'UPC'),action=actionType(body),env=await preload(),build=String(env?.build_id??decisionBuildId??''),sig=[build,family,digits(upc),action].join('|');if(body.dataset.appReadyDecision===sig)return;body.dataset.appReadyDecision=sig;const p=env?.payload||{},r=exactDecision(p,family,upc,action);if(!r)return;evidenceCell(body,'current_price','CURRENT PRICE',pick(r,'current_price','current_tpr_price','price'));evidenceCell(body,'suggested_price','SUGGESTED PRICE',pick(r,'suggested_price','suggested_tpr_price','testing_price','recommended_price'));evidenceCell(body,'current_cost','CURRENT COST',pick(r,'current_cost','cost'));evidenceCell(body,'effective_oh','EFFECTIVE OH',pick(r,'effective_oh','current_oh','ordering_oh_used','actual_position'));evidenceCell(body,'sales_7d','7D SALES',pick(r,'sales_7d','qty_7d','pos_qty_7d'));evidenceCell(body,'avg_7d','7D AVG',pick(r,'avg_7d','velocity_7d','tpr_velocity','tpr_velocity_3d','avg_per_day'));for(const [k,l] of [['forecast_usage_before_delivery','FORECAST USAGE BEFORE DELIVERY'],['projected_oh_at_delivery','PROJECTED OH AT DELIVERY'],['usable_oh_at_delivery','USABLE OH AT DELIVERY'],['pre_delivery_stockout_qty','PRE DELIVERY STOCKOUT QTY']])evidenceCell(body,k,l,pick(r,k));evidenceCell(body,'forecast_coverage_usage','FORECAST COVERAGE USAGE',pick(r,'forecast_coverage_usage','forecast_requested_coverage_usage'));evidenceCell(body,'decision_evidence_ready','DECISION EVIDENCE READY',pick(r,'decision_evidence_ready'));evidenceCell(body,'decision_missing_evidence','MISSING EVIDENCE',Array.isArray(r?.decision_missing_evidence)?r.decision_missing_evidence.join(', '):r?.decision_missing_evidence);body.dataset.appReadyBuildId=build;body.dataset.causalDecisionEvidence='';body.dispatchEvent(new CustomEvent('yipman-app-ready-decision-hydrated',{bubbles:true,detail:{buildId:build||null,actionType:action||null}}))}
const kick=()=>requestAnimationFrame(hydrate);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{preload()},{once:true});else preload();new MutationObserver(kick).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class','data-action-type']});document.addEventListener('click',()=>setTimeout(kick,0),true);})();</script>'''


def polish_decision_snapshot_html(html: str) -> str:
    if "yipmanV1DecisionSnapshotScript" in html:
        return html
    return html.replace("</body>", _SCRIPT + "</body>", 1)
